SELECT ss.store_id, ss.product_id, AVG(i.quantity) AS avg_quantity, MAX(i.quantity) AS max_quantity FROM inventory i LEFT JOIN store_sales ss ON i.store_id = ss.store_id AND i.product_id = ss.product_id WHERE MONTH(i.last_restock) IN (3, 6, 12) GROUP BY ss.store_id, ss.product_id HAVING MAX(i.quantity) >= 100;
